import re

def order_event_stream(n):
    for i in range(1, n + 1):
        yield f"order_{i}"

def solve(input_str):
    match = re.search(r"\d+", input_str)
    if not match:
        return ""
    n = int(match.group())
    lines = []
    for event in order_event_stream(n):
        lines.append(f"Processing event: {event}")
    return "\n".join(lines)

if __name__ == "__main__":
    import sys
    input_str = sys.stdin.read()
    if not input_str.strip() and len(sys.argv) > 1:
        input_str = " ".join(sys.argv[1:])
    print(solve(input_str.strip()))
